def hits(b):
    n = 0
    for c in b.legal:
        r = b.landing(c)
        if (r, c) in b.their_wins or (r + 1, c) in b.their_wins:
            n += 1 if c in (0, 1, 5, 6) else 2
    return n

def fires(b):
    return hits(b) >= 2

def level(b):
    return min(9, hits(b) * 3)

def good_threats(b):
    # opponent's threat cells on rows of the opponent's good parity
    par = 0 if not b.me_first else 1
    return [(r, c) for (r, c) in b.their_wins if r % 2 == par and (r, c) not in b.their_playable_wins]

def fires(b):
    return len(good_threats(b)) >= 1

def level(b):
    return min(9, 4 * len(good_threats(b)))

# U51 hypothesis: fires when the side to move is LOST (opponent can force a four), found by a small bitboard search.
H = 7
BOTTOM = sum(1 << (c * H) for c in range(7))
FULLCOL = [((1 << 6) - 1) << (c * H) for c in range(7)]
ORDER = [3, 2, 4, 1, 5, 0, 6]

def winning(p):
    for s in (1, H, H - 1, H + 1):
        m = p & (p >> s)
        if m & (m >> (2 * s)):
            return True
    return False

def setup(b):
    me = 0
    mask = 0
    for r in range(6):
        for c in range(7):
            v = b.grid[r][c]
            if v:
                bit = 1 << (c * H + r)
                mask |= bit
                if v == 1:
                    me |= bit
    return me, mask

def win_moves(pos, mask):
    out = []
    for c in range(7):
        if not (mask & FULLCOL[c] & (1 << (c * H + 5))):
            mv = (mask + (1 << (c * H))) & FULLCOL[c]
            if winning(pos | mv):
                out.append(c)
    return out

def solve(pos, mask, depth, budget):
    # side to move = pos. return 1 forced win within depth, -1 forced loss, 0 unknown
    budget[0] -= 1
    moves = []
    for c in ORDER:
        if not (mask & (1 << (c * H + 5))):
            moves.append(c)
    if not moves:
        return 0
    opp = pos ^ mask
    for c in moves:
        mv = (mask + (1 << (c * H))) & FULLCOL[c]
        if winning(pos | mv):
            return 1
    if depth <= 1 or budget[0] <= 0:
        return 0
    # opponent immediate threats: must block
    threats = []
    for c in moves:
        mv = (mask + (1 << (c * H))) & FULLCOL[c]
        if winning(opp | mv):
            threats.append(c)
    if len(threats) >= 2:
        return -1
    if threats:
        moves = threats
    best = -1
    for c in moves:
        mv = (mask + (1 << (c * H))) & FULLCOL[c]
        r = -solve(opp, mask | mv, depth - 1, budget)
        if r == 1:
            return 1
        if r == 0:
            best = 0
    return best

def status(b, depth=7):
    pos, mask = setup(b)
    return solve(pos, mask, depth, [4000])

def fires(b):
    return status(b) == -1

def level(b):
    s = status(b)
    if s != -1:
        return 0
    return min(9, 4 + b.ply // 8)

def poisoned(b):
    n = 0
    for c in b.legal:
        r = b.landing(c)
        if (r + 1, c) in b.their_wins and (r, c) not in b.my_wins:
            n += 1
    return n

def fires(b):
    return poisoned(b) >= 1 and len(b.my_wins) == 0

def level(b):
    if not fires(b):
        return 0
    return min(9, 3 + b.ply // 6 + poisoned(b))

